    /// Helper: build a valid RSU JSON-LD payload for testing.
    fn valid_rsu_json() -> serde_json::Value {
        json!({
            "@context": "https://kiro.ai",
            "@type": "SegmentTask",
            "id": "segment_001",
            "meta": {
                "parent_goal": "Analyze thermal anomaly in tile B02",
                "thinking_budget": "medium",
