pub struct ContextEntry {
    /// The RSU ID that produced this context (e.g. "segment_001")
    pub rsu_id: String,
    /// When this context was created (segment execution start time)
    pub created_at: DateTime<Utc>,
    /// TTL in seconds — after this duration, context is eligible for eviction
    pub ttl_seconds: u32,
    /// The segment's output content held in memory
    pub content: String,
}

impl ContextEntry {
    /// Check if this context entry has expired relative to the given time.
    pub fn is_expired(&self, current_time: DateTime<Utc>) -> bool {
        let age = current_time - self.created_at;
        age.num_seconds() >= self.ttl_seconds as i64
    }
}

pub fn is_expired(&self, current_time: DateTime<Utc>) -> bool {
