pub struct PipelineCoordinator {
    /// Decomposes high-level objectives into ordered RSU sequences
    pub(crate) segmenter: Segmenter,
    /// Non-bypassable steering layer for think-prefix injection and budget enforcement
    pub(crate) steering_ctrl: SteeringController,
    /// Pre-execution guardrail: validates RSUs before they reach the LLM
    pub(crate) input_guardrail: InputGuardrail,
    /// Post-execution guardrail: validates segment output against fidelity rules
    pub(crate) output_guardrail: OutputGuardrail,
    /// Cross-segment validator: ensures inter-segment consistency
    pub(crate) cross_validator: CrossSegmentValidator,
    /// Monitoring: rolling drift metrics and structured query interface
    pub(crate) monitor: Monitor,
    /// Maximum retries per segment before pipeline failure (Requirement 6.3: default 3)
    pub(crate) max_retries: u32,
    /// Active segment contexts tracked for TTL-based VRAM eviction (Requirement 9.5)
    pub(crate) active_contexts: Vec<ContextEntry>,
    /// Hardware profile for context pruning decisions
    pub(crate) hardware_profile: HardwareProfile,
}

impl PipelineCoordinator {
    /// Create a new PipelineCoordinator with default configuration.
    ///
    /// Uses max_retries = 3 as specified by Requirement 6.3.
    /// Defaults to low-VRAM hardware profile (Pascal GPUs: 8GB).
    pub fn new() -> Self {
        Self {
            segmenter: Segmenter,
            steering_ctrl: SteeringController::new(),
            input_guardrail: InputGuardrail::new(),
            output_guardrail: OutputGuardrail::new(),
            cross_validator: CrossSegmentValidator,
            monitor: Monitor::new(),
            max_retries: 3,
            active_contexts: Vec::new(),
            hardware_profile: HardwareProfile::low_vram(),
        }
    }

    /// Create a PipelineCoordinator with a custom max_retries value.
    pub fn with_max_retries(mut self, max_retries: u32) -> Self {
        self.max_retries = max_retries;
        self
    }

    /// Create a PipelineCoordinator with a specific hardware profile.
    pub fn with_hardware_profile(mut self, profile: HardwareProfile) -> Self {
        self.hardware_profile = profile;
        self
    }

    /// Get a reference to the monitor for querying metrics.
    pub fn monitor(&self) -> &Monitor {
        &self.monitor
    }

    /// Get a mutable reference to the monitor.
    pub fn monitor_mut(&mut self) -> &mut Monitor {
        &mut self.monitor
    }

    /// Evict expired contexts based on their TTL (Requirement 9.5).
    ///
    /// Removes context entries whose age exceeds their `ttl_seconds`.
    /// This prevents VRAM accumulation across long segment chains,
    /// which is critical for Pascal-era GPUs (GTX 1060 6GB, GTX 1070 8GB, P1000 4GB).
    ///
    /// TTL defaults:
    /// - Low budget: 15s (simple lookups — evict fast)
    /// - Medium budget: 30s (standard reasoning — moderate retention)
    /// - High budget: 60s (architecture decisions — keep longer)
    ///
    /// Integrates with `ContextPruner` for hardware-aware memory management:
    /// when aggressive pruning is enabled (low-VRAM), remaining contexts are
    /// also pruned to fit within the hardware's token budget.
    pub fn evict_expired_contexts(&mut self, current_time: DateTime<Utc>) {
        let before_count = self.active_contexts.len();

        self.active_contexts.retain(|ctx| {
            let age = current_time - ctx.created_at;
            age.num_seconds() < ctx.ttl_seconds as i64
        });

        let evicted = before_count - self.active_contexts.len();
        if evicted > 0 {
            tracing::debug!(
                evicted_count = evicted,
                remaining = self.active_contexts.len(),
                "Evicted expired contexts from active set"
            );
        }

        // Integrate with ContextPruner for hardware-aware memory management.
        // After TTL eviction, check if remaining contexts still exceed the
        // hardware budget and prune further if needed.
        if self.hardware_profile.aggressive_pruning {
            let total_content: String = self
                .active_contexts
                .iter()
                .map(|ctx| ctx.content.as_str())
                .collect::<Vec<_>>()
                .join("\n");

            // Use the hardware-appropriate token budget (low-VRAM: ~750 tokens = 3000 chars)
            let budget_tokens = if self.hardware_profile.max_vram_gb <= 8 {
                750
            } else {
                2048
            };

            if ContextPruner::exceeds_budget(&total_content, budget_tokens) {
                // Keep only the 2 most recent contexts (matching ContextPruner's strategy)
                let max_keep = 2;
                if self.active_contexts.len() > max_keep {
                    let drain_count = self.active_contexts.len() - max_keep;
                    self.active_contexts.drain(..drain_count);
                    tracing::debug!(
                        kept = max_keep,
                        "Hardware-aware pruning: trimmed active contexts to fit VRAM budget"
                    );
                }
            }
        }
    }

    /// Register a new context entry for TTL tracking.
    ///
    /// Called after a segment completes successfully to track its output
    /// in the active context set. The TTL is derived from the RSU's
    /// `context_ttl_seconds` field (which defaults based on thinking_budget).
    pub fn register_context(&mut self, rsu: &Rsu, content: String) {
        let entry = ContextEntry {
            rsu_id: rsu.id.clone(),
            created_at: Utc::now(),
            ttl_seconds: rsu.meta.context_ttl_seconds,
            content,
        };
        self.active_contexts.push(entry);
    }

    /// Get the current active contexts (for inspection/testing).
    pub fn active_contexts(&self) -> &[ContextEntry] {
        &self.active_contexts
    }

    /// Execute a full pipeline from a high-level objective.
    ///
    /// Orchestrates the complete segment chain:
    /// 1. Decompose objective into RSU sequence via Segmenter
    /// 2. For each RSU:
    ///    a. InputGuardrail validation (Requirement 4.1–4.5)
    ///    b. Execute segment phases (observation → reasoning → accuracy_check)
    ///    c. OutputGuardrail validation (Requirement 5.1–5.7)
    ///    d. CrossSegmentValidator check (Requirement 6.1, 6.5)
    ///    e. Retry with augmented steering on failure (Requirement 6.2)
    ///    f. Max 3 retries before pipeline failure (Requirement 6.3)
    ///    g. Pass output to next segment as context (Requirement 6.4)
    ///    h. Record metrics via Monitor (Requirement 11.1)
    /// 3. Return PipelineResult with all segment outputs
    ///
    /// On failure, returns a `PipelineError` containing a `FailureReport` with
    /// the `PipelineState` for resume capability (Requirement 12.3).
    ///
    /// Requirements: 6.1, 6.2, 6.3, 6.4, 11.1, 12.2, 12.3
    pub async fn execute_objective(
        &mut self,
        objective: &str,
        llm: &LlmClient,
        steering: &mut SteeringEngine,
    ) -> Result<PipelineResult> {
        let pipeline_start = Instant::now();

        // Step 1: Decompose objective into RSU sequence
        let rsus = Segmenter::decompose(objective, llm).await?;

        // Track prior outputs for cross-segment context (Requirement 6.4)
        let mut prior_outputs: Vec<SegmentOutput> = Vec::new();
        let mut pipeline_segments: Vec<PipelineSegmentOutput> = Vec::new();

        // Load a default FidelityCheck for output guardrail validation
        let fidelity_check = Self::default_fidelity_check();

        // Step 2: Execute each RSU in sequence
        for (idx, rsu) in rsus.iter().enumerate() {
            let segment_start = Instant::now();
            let mut retries: u32 = 0;
            let mut segment_completed = false;
            let mut final_output: Option<PipelineSegmentOutput> = None;

            while retries <= self.max_retries && !segment_completed {
                // Step 2a: InputGuardrail validation (Requirements 4.1–4.5)
                if let Err(e) = self.input_guardrail.validate(rsu, &prior_outputs) {
                    // Input guardrail rejection is not retryable — it's a structural issue
                    // Requirement 12.3: Preserve completed outputs for resume
                    let error_msg = format!(
                        "InputGuardrail rejected RSU '{}': {}",
                        rsu.id, e
                    );
                    return Err(self.build_pipeline_error(
                        &rsu.id,
                        idx,
                        &error_msg,
                        retries,
                        objective,
                        &rsus,
                        &pipeline_segments,
                    ));
                }

                // Step 2b: Execute segment phases (observation → reasoning → accuracy_check)
                let segment_result = self
                    .execute_segment(rsu, &prior_outputs, steering, llm)
                    .await;

                let segment_output = match segment_result {
                    Ok(output) => output,
                    Err(e) => {
                        retries += 1;
                        if retries > self.max_retries {
                            // Max retries exceeded — halt pipeline (Requirement 6.3)
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: vec![],
                                drift_score: 1.0,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            // Record failure metrics (Requirement 11.1)
                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: 1.0,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            // Requirement 12.2: Structured failure report
                            // Requirement 12.3: Preserve completed outputs for resume
                            let error_msg = format!(
                                "Segment '{}' failed after {} retries: {}",
                                rsu.id, self.max_retries, e
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                objective,
                                &rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            error = %e,
                            "Segment execution failed, retrying"
                        );
                        continue;
                    }
                };

                // Step 2c: OutputGuardrail validation (Requirements 5.1–5.7)
                // Requirement 12.5: Use stricter threshold for unsteered segments
                let output_content = Self::extract_final_content(&segment_output);
                let is_unsteered = segment_output.status == SegmentStatus::Unsteered;
                let mut drift_monitor = SCMDriftMonitor::new(HardwareProfile::medium_vram());

                let validation_result = if is_unsteered {
                    // Requirement 12.5: Lower drift threshold to 0.02 for unsteered segments
                    self.validate_with_unsteered_threshold(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                } else {
                    self.output_guardrail.validate(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                };

                if !validation_result.passed {
                    // Output guardrail failed (blocker) — retry (Requirement 5.6)
                    retries += 1;
                    if retries > self.max_retries {
                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let tokens_used = Self::total_tokens(&segment_output.phases);
                        let failed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases,
                            drift_score: validation_result.drift_score,
                            retries,
                            status: SegmentStatus::Failed,
                        };
                        pipeline_segments.push(failed_output);

                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used,
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: SegmentStatus::Failed,
                            timestamp: Utc::now(),
                        });

                        let error_msg = format!(
                            "Segment '{}' output guardrail failed after {} retries. Blockers: {:?}",
                            rsu.id, self.max_retries, validation_result.blocker_failures
                        );
                        return Err(self.build_pipeline_error(
                            &rsu.id,
                            idx,
                            &error_msg,
                            retries,
                            objective,
                            &rsus,
                            &pipeline_segments,
                        ));
                    }
                    warn!(
                        rsu_id = %rsu.id,
                        retry = retries,
                        blockers = ?validation_result.blocker_failures,
                        "Output guardrail failed, retrying segment"
                    );
                    continue;
                }

                // Step 2e: CrossSegmentValidator check (Requirement 6.1, 6.5)
                let cross_result = self.cross_validator.validate(
                    &output_content,
                    objective,
                    &prior_outputs,
                )?;

                match cross_result {
                    CrossValidationResult::Pass => {
                        // Step 2g: Success — add output to prior_outputs for next segment (Requirement 6.4)
                        prior_outputs.push(SegmentOutput {
                            rsu_id: rsu.id.clone(),
                            content: output_content.clone(),
                        });

                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let final_status = if is_unsteered {
                            SegmentStatus::Unsteered
                        } else {
                            SegmentStatus::Completed
                        };
                        let completed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases.clone(),
                            drift_score: validation_result.drift_score,
                            retries,
                            status: final_status,
                        };

                        // Step 2h: Record metrics via Monitor (Requirement 11.1)
                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used: Self::total_tokens(&segment_output.phases),
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: final_status,
                            timestamp: Utc::now(),
                        });

                        final_output = Some(completed_output);
                        segment_completed = true;
                    }
                    CrossValidationResult::Fail { violation, contradicted_segment } => {
                        // Step 2f: Cross-validation failed — reprocess with augmented steering (Requirement 6.2)
                        retries += 1;
                        if retries > self.max_retries {
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: segment_output.phases,
                                drift_score: validation_result.drift_score,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: validation_result.drift_score,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            let error_msg = format!(
                                "Segment '{}' cross-validation failed after {} retries. \
                                 Violation: {}. Contradicted segment: {:?}",
                                rsu.id, self.max_retries, violation, contradicted_segment
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                objective,
                                &rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            violation = %violation,
                            contradicted = ?contradicted_segment,
                            "Cross-segment validation failed, reprocessing with augmented steering"
                        );
                        // The retry loop will re-execute with the steering engine
                        // which will include the violation context in subsequent attempts
                        continue;
                    }
                }
            }

            // Add the completed segment output to the pipeline results
            if let Some(output) = final_output {
                pipeline_segments.push(output);
            }
        }

        // Step 3: Return PipelineResult with all segment outputs
        let total_elapsed_ms = pipeline_start.elapsed().as_millis() as u64;
        let monitoring = self.monitor.query_metrics();

        Ok(PipelineResult {
            objective: objective.to_string(),
            segments: pipeline_segments,
            total_elapsed_ms,
            monitoring,
        })
    }

    /// Resume a halted pipeline from the failed segment (Requirement 12.3).
    ///
    /// Takes a `PipelineState` (produced by a prior failed `execute_objective` call)
    /// and continues execution from the `failed_segment_index`. Previously completed
    /// segment outputs are preserved and used as prior context for subsequent segments.
    ///
    /// # Arguments
    /// * `state` - The saved pipeline state from a prior failure
    /// * `llm` - The LLM client for completions
    /// * `steering` - Mutable reference to the SteeringEngine
    ///
    /// # Returns
    /// A full `PipelineResult` combining preserved outputs with newly executed segments.
    pub async fn resume(
        &mut self,
        state: PipelineState,
        llm: &LlmClient,
        steering: &mut SteeringEngine,
    ) -> Result<PipelineResult> {
        let pipeline_start = Instant::now();

        // Reconstruct prior_outputs from completed segments for cross-segment context
        let mut prior_outputs: Vec<SegmentOutput> = state
            .completed_outputs
            .iter()
            .map(|seg| SegmentOutput {
                rsu_id: seg.rsu_id.clone(),
                content: Self::extract_final_content(seg),
            })
            .collect();

        // Start with the already-completed segment outputs
        let mut pipeline_segments: Vec<PipelineSegmentOutput> = state.completed_outputs.clone();

        let fidelity_check = Self::default_fidelity_check();

        // Resume from the failed segment index
        for idx in state.failed_segment_index..state.rsus.len() {
            let rsu = &state.rsus[idx];
            let segment_start = Instant::now();
            let mut retries: u32 = 0;
            let mut segment_completed = false;
            let mut final_output: Option<PipelineSegmentOutput> = None;

            while retries <= self.max_retries && !segment_completed {
                // InputGuardrail validation
                if let Err(e) = self.input_guardrail.validate(rsu, &prior_outputs) {
                    let error_msg = format!(
                        "InputGuardrail rejected RSU '{}' on resume: {}",
                        rsu.id, e
                    );
                    return Err(self.build_pipeline_error(
                        &rsu.id,
                        idx,
                        &error_msg,
                        retries,
                        &state.objective,
                        &state.rsus,
                        &pipeline_segments,
                    ));
                }

                // Execute segment phases
                let segment_result = self
                    .execute_segment(rsu, &prior_outputs, steering, llm)
                    .await;

                let segment_output = match segment_result {
                    Ok(output) => output,
                    Err(e) => {
                        retries += 1;
                        if retries > self.max_retries {
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: vec![],
                                drift_score: 1.0,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: 1.0,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            let error_msg = format!(
                                "Segment '{}' failed after {} retries on resume: {}",
                                rsu.id, self.max_retries, e
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                &state.objective,
                                &state.rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            error = %e,
                            "Segment execution failed on resume, retrying"
                        );
                        continue;
                    }
                };

                // OutputGuardrail validation with unsteered threshold override
                let output_content = Self::extract_final_content(&segment_output);
                let is_unsteered = segment_output.status == SegmentStatus::Unsteered;
                let mut drift_monitor = SCMDriftMonitor::new(HardwareProfile::medium_vram());

                let validation_result = if is_unsteered {
                    self.validate_with_unsteered_threshold(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                } else {
                    self.output_guardrail.validate(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                };

                if !validation_result.passed {
                    retries += 1;
                    if retries > self.max_retries {
                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let tokens_used = Self::total_tokens(&segment_output.phases);
                        let failed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases,
                            drift_score: validation_result.drift_score,
                            retries,
                            status: SegmentStatus::Failed,
                        };
                        pipeline_segments.push(failed_output);

                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used,
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: SegmentStatus::Failed,
                            timestamp: Utc::now(),
                        });

                        let error_msg = format!(
                            "Segment '{}' output guardrail failed after {} retries on resume. Blockers: {:?}",
                            rsu.id, self.max_retries, validation_result.blocker_failures
                        );
                        return Err(self.build_pipeline_error(
                            &rsu.id,
                            idx,
                            &error_msg,
                            retries,
                            &state.objective,
                            &state.rsus,
                            &pipeline_segments,
                        ));
                    }
                    warn!(
                        rsu_id = %rsu.id,
                        retry = retries,
                        blockers = ?validation_result.blocker_failures,
                        "Output guardrail failed on resume, retrying segment"
                    );
                    continue;
                }

                // CrossSegmentValidator check
                let cross_result = self.cross_validator.validate(
                    &output_content,
                    &state.objective,
                    &prior_outputs,
                )?;

                match cross_result {
                    CrossValidationResult::Pass => {
                        prior_outputs.push(SegmentOutput {
                            rsu_id: rsu.id.clone(),
                            content: output_content.clone(),
                        });

                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let final_status = if is_unsteered {
                            SegmentStatus::Unsteered
                        } else {
                            SegmentStatus::Completed
                        };
                        let completed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases.clone(),
                            drift_score: validation_result.drift_score,
                            retries,
                            status: final_status,
                        };

                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used: Self::total_tokens(&segment_output.phases),
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: final_status,
                            timestamp: Utc::now(),
                        });

                        final_output = Some(completed_output);
                        segment_completed = true;
                    }
                    CrossValidationResult::Fail { violation, contradicted_segment } => {
                        retries += 1;
                        if retries > self.max_retries {
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: segment_output.phases,
                                drift_score: validation_result.drift_score,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: validation_result.drift_score,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            let error_msg = format!(
                                "Segment '{}' cross-validation failed after {} retries on resume. \
                                 Violation: {}. Contradicted segment: {:?}",
                                rsu.id, self.max_retries, violation, contradicted_segment
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                &state.objective,
                                &state.rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            violation = %violation,
                            contradicted = ?contradicted_segment,
                            "Cross-segment validation failed on resume, reprocessing"
                        );
                        continue;
                    }
                }
            }

            if let Some(output) = final_output {
                pipeline_segments.push(output);
            }
        }

        // Return full PipelineResult combining preserved + new outputs
        let total_elapsed_ms = pipeline_start.elapsed().as_millis() as u64;
        let monitoring = self.monitor.query_metrics();

        Ok(PipelineResult {
            objective: state.objective,
            segments: pipeline_segments,
            total_elapsed_ms,
            monitoring,
        })
    }

    // ── Private helpers ──────────────────────────────────────────────────────

    /// Extract the final content from a segment's phase outputs.
    /// Uses the last phase (accuracy_check) content as the segment's output.
    fn extract_final_content(output: &PipelineSegmentOutput) -> String {
        output
            .phases
            .last()
            .map(|p| p.content.clone())
            .unwrap_or_default()
    }

    /// Sum total tokens used across all phases.
    fn total_tokens(phases: &[PhaseOutput]) -> u32 {
        phases.iter().map(|p| p.tokens_used).sum()
    }

    /// Map an RSU's steering policy mode to the monitor's SegmentMode.
    fn rsu_to_segment_mode(rsu: &Rsu) -> SegmentMode {
        match rsu.meta.steering_policy.mode {
            super::rsu::SegmentMode::Precision => SegmentMode::Precision,
            super::rsu::SegmentMode::Exploratory => SegmentMode::Exploratory,
        }
    }

    /// Create a default FidelityCheck for output guardrail validation.
    /// In production, this would be loaded from the RSU's `steering_ref` path.
    fn default_fidelity_check() -> FidelityCheck {
        FidelityCheck {
            context: "https://kiro.ai".to_string(),
            check_type: "FidelityCheck".to_string(),
            validation_rules: vec![
                ValidationRule {
                    rule: "strict_schema_enforcement".to_string(),
                    description: "Output must not contain fields or structures not defined in the validated schema".to_string(),
                    severity: RuleSeverity::Blocker,
                },
                ValidationRule {
                    rule: "canonical_serialization".to_string(),
                    description: "Tool calls must be regenerated through the trusted serializer".to_string(),
                    severity: RuleSeverity::Blocker,
                },
            ],
            monitoring: MonitoringConfig {
                threshold: 0.05,
                rolling_window: 5,
                escalation_threshold: 0.03,
            },
        }
    }

    /// Execute a single segment (RSU) through the three-phase pipeline.
    ///
    /// Enforces strict phase ordering: Observation → Reasoning → AccuracyCheck.
    /// Chains outputs between phases and handles accuracy_check failures by
    /// reprocessing the reasoning phase with violation feedback.
    ///
    /// # Phase Execution (Requirements 8.1, 8.2, 8.3, 8.5)
    ///
    /// 1. **Observation** (Req 8.1): Gathers context from prior segments and nautivecs.
    ///    The RSU's `phases.observation` prompt is executed with prior segment outputs
    ///    available as context.
    ///
    /// 2. **Reasoning** (Req 8.2): Uses observation output as input context.
    ///    The RSU's `phases.reasoning` prompt is executed with the observation output
    ///    fed in as `prior_output`.
    ///
    /// 3. **AccuracyCheck** (Req 8.3): Verifies reasoning output satisfies the constraint.
    ///    The RSU's `phases.accuracy_check` prompt is executed with the reasoning output
    ///    fed in as `prior_output`.
    ///
    /// # Retry on Accuracy Failure (Requirement 8.4)
    ///
    /// If the accuracy_check output contains "FAIL", the reasoning phase is reprocessed
    /// with the violation feedback included in the steering vector. This retry loop
    /// continues up to `self.max_retries` times.
    ///
    /// # Arguments
    /// * `rsu` - The RSU to execute
    /// * `prior_segment_outputs` - Outputs from previously completed segments (for context)
    /// * `steering` - Mutable reference to the SteeringEngine for nautivecs queries
    /// * `llm` - The LLM client for completions
    ///
    /// # Returns
    /// `PipelineSegmentOutput` containing all phase outputs, drift score, retries, and status.
    pub async fn execute_segment(
        &mut self,
        rsu: &Rsu,
        prior_segment_outputs: &[SegmentOutput],
        steering: &mut SteeringEngine,
        llm: &LlmClient,
    ) -> Result<PipelineSegmentOutput> {
        let segment_start = Instant::now();
        let mut budget = SteeringController::budget_for_rsu(rsu);
        let mut phase_outputs: Vec<PhaseOutput> = Vec::with_capacity(3);
        let mut retries: u32 = 0;
        let mut unsteered = false;

        // ── Context TTL Eviction (Requirement 9.5) ───────────────────────────
        // Evict expired contexts at the start of each segment execution to
        // prevent VRAM accumulation across long segment chains.
        self.evict_expired_contexts(Utc::now());

        // ── Phase 1: Observation (Requirement 8.1) ───────────────────────────
        // Gather context from prior segments and nautivecs.
        // Build prior context string from prior_segment_outputs for the observation phase.
        let prior_context: Option<String> = if prior_segment_outputs.is_empty() {
            None
        } else {
            let ctx = prior_segment_outputs
                .iter()
                .map(|o| format!("[{}]: {}", o.rsu_id, o.content))
                .collect::<Vec<_>>()
                .join("\n");
            Some(ctx)
        };

        let obs_start = Instant::now();
        let obs_result = self
            .retry_with_backoff(
                rsu,
                Phase::Observation,
                prior_context.as_deref(),
                steering,
                llm,
            )
            .await?;

        let obs_budget_result =
            SteeringController::enforce_budget(&mut budget, Phase::Observation, &obs_result.response);
        if obs_result.unsteered {
            unsteered = true;
        }

        let observation_output = obs_budget_result.content.clone();
        phase_outputs.push(PhaseOutput {
            phase: Phase::Observation,
            content: obs_budget_result.content,
            tokens_used: obs_budget_result.tokens_used,
            elapsed_ms: obs_start.elapsed().as_millis() as u64,
        });

        // ── Phase 2: Reasoning (Requirement 8.2) ────────────────────────────
        // Use observation output as input to reasoning phase.
        let mut reasoning_output = self
            .execute_reasoning_phase(rsu, &observation_output, &mut budget, steering, llm)
            .await?;

        phase_outputs.push(reasoning_output.phase_output.clone());
        if reasoning_output.unsteered {
            unsteered = true;
        }

        // ── Phase 3: AccuracyCheck (Requirement 8.3) ────────────────────────
        // Verify reasoning output in accuracy_check phase.
        let mut acc_result = self
            .execute_accuracy_check_phase(rsu, &reasoning_output.content, &mut budget, steering, llm)
            .await?;

        if acc_result.unsteered {
            unsteered = true;
        }

        // ── Retry Loop (Requirement 8.4) ────────────────────────────────────
        // If accuracy_check fails, reprocess reasoning with violation feedback.
        while self.accuracy_check_failed(&acc_result.content) && retries < self.max_retries {
            retries += 1;
            tracing::warn!(
                rsu_id = %rsu.id,
                retry = retries,
                "Accuracy check failed — reprocessing reasoning with violation feedback"
            );

            // Build violation feedback from the accuracy check output
            let violation_feedback = format!(
                "PREVIOUS ACCURACY CHECK FAILED: {}\nReprocess reasoning to satisfy the constraint.",
                acc_result.content
            );

            // Reprocess reasoning with violation feedback as additional context
            let augmented_input = format!(
                "{}\n\n[VIOLATION FEEDBACK]: {}",
                observation_output, violation_feedback
            );

            reasoning_output = self
                .execute_reasoning_phase(rsu, &augmented_input, &mut budget, steering, llm)
                .await?;

            // Replace the reasoning phase output in our list
            if phase_outputs.len() >= 2 {
                phase_outputs[1] = reasoning_output.phase_output.clone();
            }

            // Re-run accuracy check on the new reasoning output
            acc_result = self
                .execute_accuracy_check_phase(
                    rsu,
                    &reasoning_output.content,
                    &mut budget,
                    steering,
                    llm,
                )
                .await?;
        }

        // Add the final accuracy check phase output
        phase_outputs.push(acc_result.phase_output);

        // ── Compute drift score ──────────────────────────────────────────────
        // Use a simple heuristic: if accuracy check passed, drift is low.
        // If it failed after retries, drift is high.
        let drift_score = if self.accuracy_check_failed(&acc_result.content) {
            // Failed even after retries — high drift
            0.8
        } else if retries > 0 {
            // Passed after retries — moderate drift proportional to retry count
            0.05 * retries as f32
        } else {
            // Passed first time — minimal drift
            0.01
        };

        // ── Determine final status ──────────────────────────────────────────
        let status = if self.accuracy_check_failed(&acc_result.content) {
            SegmentStatus::Failed
        } else if budget.budget_exhausted {
            SegmentStatus::BudgetExhausted
        } else if unsteered {
            SegmentStatus::Unsteered
        } else {
            SegmentStatus::Completed
        };

        let _total_elapsed = segment_start.elapsed().as_millis() as u64;

        // ── Register context for TTL tracking (Requirement 9.5) ──────────────
        // After successful execution, register this segment's output in the
        // active context set so it can be evicted when its TTL expires.
        if status == SegmentStatus::Completed || status == SegmentStatus::BudgetExhausted {
            let final_content = phase_outputs
                .last()
                .map(|p| p.content.clone())
                .unwrap_or_default();
            self.register_context(rsu, final_content);
        }

        Ok(PipelineSegmentOutput {
            rsu_id: rsu.id.clone(),
            phases: phase_outputs,
            drift_score,
            retries,
            status,
        })
    }

    // ── Private helpers for execute_segment ──────────────────────────────────

    /// Execute the reasoning phase and return the result with metadata.
    async fn execute_reasoning_phase(
        &self,
        rsu: &Rsu,
        observation_output: &str,
        budget: &mut BudgetConfig,
        steering: &mut SteeringEngine,
        llm: &LlmClient,
    ) -> Result<PhaseExecutionResult> {
        let start = Instant::now();
        let result = self
            .retry_with_backoff(
                rsu,
                Phase::Reasoning,
                Some(observation_output),
                steering,
                llm,
            )
            .await?;

        let budget_result =
            SteeringController::enforce_budget(budget, Phase::Reasoning, &result.response);

        Ok(PhaseExecutionResult {
            content: budget_result.content.clone(),
            unsteered: result.unsteered,
            phase_output: PhaseOutput {
                phase: Phase::Reasoning,
                content: budget_result.content,
                tokens_used: budget_result.tokens_used,
                elapsed_ms: start.elapsed().as_millis() as u64,
            },
        })
    }

    /// Execute the accuracy check phase and return the result with metadata.
    async fn execute_accuracy_check_phase(
        &self,
        rsu: &Rsu,
        reasoning_output: &str,
        budget: &mut BudgetConfig,
        steering: &mut SteeringEngine,
        llm: &LlmClient,
    ) -> Result<PhaseExecutionResult> {
        let start = Instant::now();
        let result = self
            .retry_with_backoff(
                rsu,
                Phase::AccuracyCheck,
                Some(reasoning_output),
                steering,
                llm,
            )
            .await?;

        let budget_result =
            SteeringController::enforce_budget(budget, Phase::AccuracyCheck, &result.response);

        Ok(PhaseExecutionResult {
            content: budget_result.content.clone(),
            unsteered: result.unsteered,
            phase_output: PhaseOutput {
                phase: Phase::AccuracyCheck,
                content: budget_result.content,
                tokens_used: budget_result.tokens_used,
                elapsed_ms: start.elapsed().as_millis() as u64,
            },
        })
    }

    /// Determine if the accuracy check output indicates a failure.
    ///
    /// Checks for "FAIL" at the start of the output (case-insensitive),
    /// which is the expected format from the accuracy check phase prompt.
    fn accuracy_check_failed(&self, accuracy_output: &str) -> bool {
        let trimmed = accuracy_output.trim().to_uppercase();
        trimmed.starts_with("FAIL")
    }

    /// Build a structured pipeline error with a failure report and preserved state
    /// for resume capability (Requirements 12.2, 12.3).
    ///
    /// This creates a `PipelineError` containing:
    /// - The failed RSU ID and index
    /// - A human-readable error message
    /// - The number of retries attempted
    /// - A `PipelineState` with all completed outputs preserved for resume
    ///
    /// The returned error is wrapped in `anyhow::Error` for propagation through `Result`.
    fn build_pipeline_error(
        &self,
        failed_rsu_id: &str,
        failed_segment_index: usize,
        error_message: &str,
        retries_attempted: u32,
        objective: &str,
        rsus: &[Rsu],
        completed_outputs: &[PipelineSegmentOutput],
    ) -> anyhow::Error {
        let pipeline_state = PipelineState {
            objective: objective.to_string(),
            rsus: rsus.to_vec(),
            completed_outputs: completed_outputs.to_vec(),
            failed_segment_index,
            retry_count: retries_attempted,
        };

        let report = FailureReport {
            failed_rsu_id: failed_rsu_id.to_string(),
            failed_segment_index,
            error_message: error_message.to_string(),
            retries_attempted,
            pipeline_state,
            timestamp: Utc::now(),
        };

        PipelineError { report }.into()
    }

    /// Validate output with the stricter unsteered drift threshold (Requirement 12.5).
    ///
    /// When a segment runs without nautivecs steering context (store unreachable),
    /// the drift threshold is lowered to 0.02 regardless of the RSU's configured
    /// threshold. This ensures unsteered segments are held to a higher standard
    /// since they lack the grounding context that normally prevents drift.
    ///
    /// This method creates a temporary RSU clone with the overridden threshold
    /// and delegates to the standard `OutputGuardrail::validate`.
    fn validate_with_unsteered_threshold(
        &self,
        output: &str,
        rsu: &Rsu,
        fidelity_check: &FidelityCheck,
        monitor: &mut dyn DriftMonitor,
    ) -> Result<ValidationResult> {
        // Clone the RSU and override its drift threshold to the unsteered value (0.02)
        let mut unsteered_rsu = rsu.clone();
        unsteered_rsu.meta.steering_policy.drift_threshold = UNSTEERED_DRIFT_THRESHOLD;

        self.output_guardrail
            .validate(output, &unsteered_rsu, fidelity_check, monitor)
    }

    /// Retry a single phase execution once after a 2-second backoff on LLM error
    /// (Requirement 12.1).
    ///
    /// Calls `steer_and_execute` and, if it returns an error, waits 2 seconds
    /// and retries exactly once. If the retry also fails, the error is propagated
    /// to the caller (which will mark the segment as failed per Requirement 12.2).
    ///
    /// # Arguments
    /// * `rsu` - The RSU being executed
    /// * `phase` - Which phase to execute
    /// * `prior_output` - Output from the previous phase (if any)
    /// * `steering` - Mutable reference to the SteeringEngine
    /// * `llm` - The LLM client
    ///
    /// # Returns
    /// The `SteerResult` on success, or the retry error on double failure.
    async fn retry_with_backoff(
        &self,
        rsu: &Rsu,
        phase: Phase,
        prior_output: Option<&str>,
        steering: &mut SteeringEngine,
        llm: &LlmClient,
    ) -> Result<SteerResult> {
        // First attempt
        let first_attempt = self
            .steering_ctrl
            .steer_and_execute(rsu, phase, prior_output, steering, llm)
            .await;

        match first_attempt {
            Ok(result) => Ok(result),
            Err(first_error) => {
                // Requirement 12.1: Wait 2 seconds before retrying
                warn!(
                    rsu_id = %rsu.id,
                    phase = ?phase,
                    error = %first_error,
                    "LLM call failed, retrying after 2-second backoff"
                );
                sleep(LLM_RETRY_BACKOFF).await;

                // Single retry attempt
                self.steering_ctrl
                    .steer_and_execute(rsu, phase, prior_output, steering, llm)
                    .await
            }
        }
    }
}

pub fn new() -> Self {
        Self {
            segmenter: Segmenter,
            steering_ctrl: SteeringController::new(),
            input_guardrail: InputGuardrail::new(),
            output_guardrail: OutputGuardrail::new(),
            cross_validator: CrossSegmentValidator,
            monitor: Monitor::new(),
            max_retries: 3,
            active_contexts: Vec::new(),
            hardware_profile: HardwareProfile::low_vram(),
        }
    }

pub fn with_max_retries(mut self, max_retries: u32) -> Self {
        self.max_retries = max_retries;
        self
    }

pub fn with_hardware_profile(mut self, profile: HardwareProfile) -> Self {
        self.hardware_profile = profile;
        self
    }

pub fn monitor(&self) -> &Monitor {
        &self.monitor
    }

pub fn monitor_mut(&mut self) -> &mut Monitor {
        &mut self.monitor
    }

pub fn evict_expired_contexts(&mut self, current_time: DateTime<Utc>) {
        let before_count = self.active_contexts.len();

        self.active_contexts.retain(|ctx| {
            let age = current_time - ctx.created_at;
            age.num_seconds() < ctx.ttl_seconds as i64
        });

        let evicted = before_count - self.active_contexts.len();
        if evicted > 0 {
            tracing::debug!(
                evicted_count = evicted,
                remaining = self.active_contexts.len(),
                "Evicted expired contexts from active set"
            );
        }

        // Integrate with ContextPruner for hardware-aware memory management.
        // After TTL eviction, check if remaining contexts still exceed the
        // hardware budget and prune further if needed.
        if self.hardware_profile.aggressive_pruning {
            let total_content: String = self
                .active_contexts
                .iter()
                .map(|ctx| ctx.content.as_str())
                .collect::<Vec<_>>()
                .join("\n");

            // Use the hardware-appropriate token budget (low-VRAM: ~750 tokens = 3000 chars)
            let budget_tokens = if self.hardware_profile.max_vram_gb <= 8 {
                750
            } else {
                2048
            };

            if ContextPruner::exceeds_budget(&total_content, budget_tokens) {
                // Keep only the 2 most recent contexts (matching ContextPruner's strategy)
                let max_keep = 2;
                if self.active_contexts.len() > max_keep {
                    let drain_count = self.active_contexts.len() - max_keep;
                    self.active_contexts.drain(..drain_count);
                    tracing::debug!(
                        kept = max_keep,
                        "Hardware-aware pruning: trimmed active contexts to fit VRAM budget"
                    );
                }
            }
        }
    }

pub fn register_context(&mut self, rsu: &Rsu, content: String) {
        let entry = ContextEntry {
            rsu_id: rsu.id.clone(),
            created_at: Utc::now(),
            ttl_seconds: rsu.meta.context_ttl_seconds,
            content,
        };
        self.active_contexts.push(entry);
    }

pub fn active_contexts(&self) -> &[ContextEntry] {
        &self.active_contexts
    }

pub async fn execute_objective(
        &mut self,
        objective: &str,
        llm: &LlmClient,
        steering: &mut SteeringEngine,
    ) -> Result<PipelineResult> {
        let pipeline_start = Instant::now();

        // Step 1: Decompose objective into RSU sequence
        let rsus = Segmenter::decompose(objective, llm).await?;

        // Track prior outputs for cross-segment context (Requirement 6.4)
        let mut prior_outputs: Vec<SegmentOutput> = Vec::new();
        let mut pipeline_segments: Vec<PipelineSegmentOutput> = Vec::new();

        // Load a default FidelityCheck for output guardrail validation
        let fidelity_check = Self::default_fidelity_check();

        // Step 2: Execute each RSU in sequence
        for (idx, rsu) in rsus.iter().enumerate() {
            let segment_start = Instant::now();
            let mut retries: u32 = 0;
            let mut segment_completed = false;
            let mut final_output: Option<PipelineSegmentOutput> = None;

            while retries <= self.max_retries && !segment_completed {
                // Step 2a: InputGuardrail validation (Requirements 4.1–4.5)
                if let Err(e) = self.input_guardrail.validate(rsu, &prior_outputs) {
                    // Input guardrail rejection is not retryable — it's a structural issue
                    // Requirement 12.3: Preserve completed outputs for resume
                    let error_msg = format!(
                        "InputGuardrail rejected RSU '{}': {}",
                        rsu.id, e
                    );
                    return Err(self.build_pipeline_error(
                        &rsu.id,
                        idx,
                        &error_msg,
                        retries,
                        objective,
                        &rsus,
                        &pipeline_segments,
                    ));
                }

                // Step 2b: Execute segment phases (observation → reasoning → accuracy_check)
                let segment_result = self
                    .execute_segment(rsu, &prior_outputs, steering, llm)
                    .await;

                let segment_output = match segment_result {
                    Ok(output) => output,
                    Err(e) => {
                        retries += 1;
                        if retries > self.max_retries {
                            // Max retries exceeded — halt pipeline (Requirement 6.3)
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: vec![],
                                drift_score: 1.0,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            // Record failure metrics (Requirement 11.1)
                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: 1.0,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            // Requirement 12.2: Structured failure report
                            // Requirement 12.3: Preserve completed outputs for resume
                            let error_msg = format!(
                                "Segment '{}' failed after {} retries: {}",
                                rsu.id, self.max_retries, e
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                objective,
                                &rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            error = %e,
                            "Segment execution failed, retrying"
                        );
                        continue;
                    }
                };

                // Step 2c: OutputGuardrail validation (Requirements 5.1–5.7)
                // Requirement 12.5: Use stricter threshold for unsteered segments
                let output_content = Self::extract_final_content(&segment_output);
                let is_unsteered = segment_output.status == SegmentStatus::Unsteered;
                let mut drift_monitor = SCMDriftMonitor::new(HardwareProfile::medium_vram());

                let validation_result = if is_unsteered {
                    // Requirement 12.5: Lower drift threshold to 0.02 for unsteered segments
                    self.validate_with_unsteered_threshold(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                } else {
                    self.output_guardrail.validate(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                };

                if !validation_result.passed {
                    // Output guardrail failed (blocker) — retry (Requirement 5.6)
                    retries += 1;
                    if retries > self.max_retries {
                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let tokens_used = Self::total_tokens(&segment_output.phases);
                        let failed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases,
                            drift_score: validation_result.drift_score,
                            retries,
                            status: SegmentStatus::Failed,
                        };
                        pipeline_segments.push(failed_output);

                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used,
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: SegmentStatus::Failed,
                            timestamp: Utc::now(),
                        });

                        let error_msg = format!(
                            "Segment '{}' output guardrail failed after {} retries. Blockers: {:?}",
                            rsu.id, self.max_retries, validation_result.blocker_failures
                        );
                        return Err(self.build_pipeline_error(
                            &rsu.id,
                            idx,
                            &error_msg,
                            retries,
                            objective,
                            &rsus,
                            &pipeline_segments,
                        ));
                    }
                    warn!(
                        rsu_id = %rsu.id,
                        retry = retries,
                        blockers = ?validation_result.blocker_failures,
                        "Output guardrail failed, retrying segment"
                    );
                    continue;
                }

                // Step 2e: CrossSegmentValidator check (Requirement 6.1, 6.5)
                let cross_result = self.cross_validator.validate(
                    &output_content,
                    objective,
                    &prior_outputs,
                )?;

                match cross_result {
                    CrossValidationResult::Pass => {
                        // Step 2g: Success — add output to prior_outputs for next segment (Requirement 6.4)
                        prior_outputs.push(SegmentOutput {
                            rsu_id: rsu.id.clone(),
                            content: output_content.clone(),
                        });

                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let final_status = if is_unsteered {
                            SegmentStatus::Unsteered
                        } else {
                            SegmentStatus::Completed
                        };
                        let completed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases.clone(),
                            drift_score: validation_result.drift_score,
                            retries,
                            status: final_status,
                        };

                        // Step 2h: Record metrics via Monitor (Requirement 11.1)
                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used: Self::total_tokens(&segment_output.phases),
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: final_status,
                            timestamp: Utc::now(),
                        });

                        final_output = Some(completed_output);
                        segment_completed = true;
                    }
                    CrossValidationResult::Fail { violation, contradicted_segment } => {
                        // Step 2f: Cross-validation failed — reprocess with augmented steering (Requirement 6.2)
                        retries += 1;
                        if retries > self.max_retries {
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: segment_output.phases,
                                drift_score: validation_result.drift_score,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: validation_result.drift_score,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            let error_msg = format!(
                                "Segment '{}' cross-validation failed after {} retries. \
                                 Violation: {}. Contradicted segment: {:?}",
                                rsu.id, self.max_retries, violation, contradicted_segment
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                objective,
                                &rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            violation = %violation,
                            contradicted = ?contradicted_segment,
                            "Cross-segment validation failed, reprocessing with augmented steering"
                        );
                        // The retry loop will re-execute with the steering engine
                        // which will include the violation context in subsequent attempts
                        continue;
                    }
                }
            }

            // Add the completed segment output to the pipeline results
            if let Some(output) = final_output {
                pipeline_segments.push(output);
            }
        }

        // Step 3: Return PipelineResult with all segment outputs
        let total_elapsed_ms = pipeline_start.elapsed().as_millis() as u64;
        let monitoring = self.monitor.query_metrics();

        Ok(PipelineResult {
            objective: objective.to_string(),
            segments: pipeline_segments,
            total_elapsed_ms,
            monitoring,
        })
    }

pub async fn resume(
        &mut self,
        state: PipelineState,
        llm: &LlmClient,
        steering: &mut SteeringEngine,
    ) -> Result<PipelineResult> {
        let pipeline_start = Instant::now();

        // Reconstruct prior_outputs from completed segments for cross-segment context
        let mut prior_outputs: Vec<SegmentOutput> = state
            .completed_outputs
            .iter()
            .map(|seg| SegmentOutput {
                rsu_id: seg.rsu_id.clone(),
                content: Self::extract_final_content(seg),
            })
            .collect();

        // Start with the already-completed segment outputs
        let mut pipeline_segments: Vec<PipelineSegmentOutput> = state.completed_outputs.clone();

        let fidelity_check = Self::default_fidelity_check();

        // Resume from the failed segment index
        for idx in state.failed_segment_index..state.rsus.len() {
            let rsu = &state.rsus[idx];
            let segment_start = Instant::now();
            let mut retries: u32 = 0;
            let mut segment_completed = false;
            let mut final_output: Option<PipelineSegmentOutput> = None;

            while retries <= self.max_retries && !segment_completed {
                // InputGuardrail validation
                if let Err(e) = self.input_guardrail.validate(rsu, &prior_outputs) {
                    let error_msg = format!(
                        "InputGuardrail rejected RSU '{}' on resume: {}",
                        rsu.id, e
                    );
                    return Err(self.build_pipeline_error(
                        &rsu.id,
                        idx,
                        &error_msg,
                        retries,
                        &state.objective,
                        &state.rsus,
                        &pipeline_segments,
                    ));
                }

                // Execute segment phases
                let segment_result = self
                    .execute_segment(rsu, &prior_outputs, steering, llm)
                    .await;

                let segment_output = match segment_result {
                    Ok(output) => output,
                    Err(e) => {
                        retries += 1;
                        if retries > self.max_retries {
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: vec![],
                                drift_score: 1.0,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: 1.0,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            let error_msg = format!(
                                "Segment '{}' failed after {} retries on resume: {}",
                                rsu.id, self.max_retries, e
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                &state.objective,
                                &state.rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            error = %e,
                            "Segment execution failed on resume, retrying"
                        );
                        continue;
                    }
                };

                // OutputGuardrail validation with unsteered threshold override
                let output_content = Self::extract_final_content(&segment_output);
                let is_unsteered = segment_output.status == SegmentStatus::Unsteered;
                let mut drift_monitor = SCMDriftMonitor::new(HardwareProfile::medium_vram());

                let validation_result = if is_unsteered {
                    self.validate_with_unsteered_threshold(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                } else {
                    self.output_guardrail.validate(
                        &output_content,
                        rsu,
                        &fidelity_check,
                        &mut drift_monitor,
                    )?
                };

                if !validation_result.passed {
                    retries += 1;
                    if retries > self.max_retries {
                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let tokens_used = Self::total_tokens(&segment_output.phases);
                        let failed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases,
                            drift_score: validation_result.drift_score,
                            retries,
                            status: SegmentStatus::Failed,
                        };
                        pipeline_segments.push(failed_output);

                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used,
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: SegmentStatus::Failed,
                            timestamp: Utc::now(),
                        });

                        let error_msg = format!(
                            "Segment '{}' output guardrail failed after {} retries on resume. Blockers: {:?}",
                            rsu.id, self.max_retries, validation_result.blocker_failures
                        );
                        return Err(self.build_pipeline_error(
                            &rsu.id,
                            idx,
                            &error_msg,
                            retries,
                            &state.objective,
                            &state.rsus,
                            &pipeline_segments,
                        ));
                    }
                    warn!(
                        rsu_id = %rsu.id,
                        retry = retries,
                        blockers = ?validation_result.blocker_failures,
                        "Output guardrail failed on resume, retrying segment"
                    );
                    continue;
                }

                // CrossSegmentValidator check
                let cross_result = self.cross_validator.validate(
                    &output_content,
                    &state.objective,
                    &prior_outputs,
                )?;

                match cross_result {
                    CrossValidationResult::Pass => {
                        prior_outputs.push(SegmentOutput {
                            rsu_id: rsu.id.clone(),
                            content: output_content.clone(),
                        });

                        let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                        let final_status = if is_unsteered {
                            SegmentStatus::Unsteered
                        } else {
                            SegmentStatus::Completed
                        };
                        let completed_output = PipelineSegmentOutput {
                            rsu_id: rsu.id.clone(),
                            phases: segment_output.phases.clone(),
                            drift_score: validation_result.drift_score,
                            retries,
                            status: final_status,
                        };

                        self.monitor.record(SegmentMetrics {
                            rsu_id: rsu.id.clone(),
                            drift_score: validation_result.drift_score,
                            tokens_used: Self::total_tokens(&segment_output.phases),
                            retries,
                            elapsed_ms,
                            segment_mode: Self::rsu_to_segment_mode(rsu),
                            status: final_status,
                            timestamp: Utc::now(),
                        });

                        final_output = Some(completed_output);
                        segment_completed = true;
                    }
                    CrossValidationResult::Fail { violation, contradicted_segment } => {
                        retries += 1;
                        if retries > self.max_retries {
                            let elapsed_ms = segment_start.elapsed().as_millis() as u64;
                            let failed_output = PipelineSegmentOutput {
                                rsu_id: rsu.id.clone(),
                                phases: segment_output.phases,
                                drift_score: validation_result.drift_score,
                                retries,
                                status: SegmentStatus::Failed,
                            };
                            pipeline_segments.push(failed_output);

                            self.monitor.record(SegmentMetrics {
                                rsu_id: rsu.id.clone(),
                                drift_score: validation_result.drift_score,
                                tokens_used: 0,
                                retries,
                                elapsed_ms,
                                segment_mode: Self::rsu_to_segment_mode(rsu),
                                status: SegmentStatus::Failed,
                                timestamp: Utc::now(),
                            });

                            let error_msg = format!(
                                "Segment '{}' cross-validation failed after {} retries on resume. \
                                 Violation: {}. Contradicted segment: {:?}",
                                rsu.id, self.max_retries, violation, contradicted_segment
                            );
                            return Err(self.build_pipeline_error(
                                &rsu.id,
                                idx,
                                &error_msg,
                                retries,
                                &state.objective,
                                &state.rsus,
                                &pipeline_segments,
                            ));
                        }
                        warn!(
                            rsu_id = %rsu.id,
                            retry = retries,
                            violation = %violation,
                            contradicted = ?contradicted_segment,
                            "Cross-segment validation failed on resume, reprocessing"
                        );
                        continue;
                    }
                }
            }

            if let Some(output) = final_output {
                pipeline_segments.push(output);
            }
        }

        // Return full PipelineResult combining preserved + new outputs
        let total_elapsed_ms = pipeline_start.elapsed().as_millis() as u64;
        let monitoring = self.monitor.query_metrics();

        Ok(PipelineResult {
            objective: state.objective,
            segments: pipeline_segments,
            total_elapsed_ms,
            monitoring,
        })
    }

fn total_tokens(phases: &[PhaseOutput]) -> u32 {
        phases.iter().map(|p| p.tokens_used).sum()
    }

fn rsu_to_segment_mode(rsu: &Rsu) -> SegmentMode {
        match rsu.meta.steering_policy.mode {
            super::rsu::SegmentMode::Precision => SegmentMode::Precision,
            super::rsu::SegmentMode::Exploratory => SegmentMode::Exploratory,
        }
    }

