                action: "queryNautivecs".to_string(),
                parameters: serde_json::json!({}),
            },
            dependencies: vec!["segment_000".to_string()],
        };

        // Simulate: segment_000 completed, segment_001 failed
        let state = PipelineState {
            objective: "Multi-segment task".to_string(),
            rsus: vec![rsu_0, rsu_1],
            completed_outputs: vec![PipelineSegmentOutput {
                rsu_id: "segment_000".to_string(),
                phases: vec![
                    PhaseOutput {
                        phase: Phase::Observation,
                        content: "Context gathered.".to_string(),
