fn test_hardware_aware_pruning_trims_excess_contexts() {
        // Low-VRAM profile triggers aggressive pruning
        let mut coordinator = PipelineCoordinator::new()
            .with_hardware_profile(HardwareProfile::low_vram());
        let now = Utc::now();

        // Add 5 non-expired contexts with large content (exceeds budget)
        for i in 0..5 {
            coordinator.active_contexts.push(ContextEntry {
                rsu_id: format!("segment_{:03}", i),
                created_at: now - chrono::Duration::seconds(1),
                ttl_seconds: 60,
                // Each context is ~1000 chars → 5 × 1000 = 5000 chars ≈ 1250 tokens > 750 budget
                content: "x".repeat(1000),
            });
        }

        coordinator.evict_expired_contexts(now);

        // Should be trimmed to 2 most recent (hardware-aware pruning)
        assert_eq!(coordinator.active_contexts.len(), 2);
        // The 2 most recent should be kept (last two added)
        assert_eq!(coordinator.active_contexts[0].rsu_id, "segment_003");
        assert_eq!(coordinator.active_contexts[1].rsu_id, "segment_004");
    }

