    fn test_circular_overwrites() {
        let mut rd = RollingDrift::new(3);
        rd.push(0.01);
        rd.push(0.02);
        rd.push(0.03);
        rd.push(0.04); // overwrites 0.01

        assert_eq!(rd.len(), 3);
        assert!(rd.is_full());
        // Window should be [0.04, 0.02, 0.03] (pointer wrapped)
        let avg = rd.raw_average();
        assert!((avg - 0.03).abs() < 0.001);
    }
