            return 0.0;
        }
        self.history.iter().map(|(s, w)| s * w).sum::<f64>() / total_weight
    }

pub fn len(&self) -> usize {
        self.history.len()
    }

pub fn is_empty(&self) -> bool {
        self.history.is_empty()
    }

