    fn select_monitor(&self, policy: &SteeringPolicy) -> Box<dyn DriftMonitor> {
        match policy.mode {
            SegmentMode::Precision => Box::new(StrictDriftMonitor {
                threshold: policy.drift_threshold, // 0.05
